"use strict";
// logger.lib.civet

import {cyan, red, yellow} from '@std/fmt/colors'
import {existsSync} from '@std/fs'

export let logWidth = 78

export type TLogLevel = 'testing' | 'silent' | 'info' | 'debug'
export let lLogLevels: TLogLevel[] = ['info']
export let logLevel: TLogLevel = 'info'
export const getLogLevels = () => { return lLogLevels }

// ---------------------------------------------------------------------------

export const stringFits = (
		str: string,
		width: number = logWidth
		): boolean => {

	return (str.length <= width)
}

// ---------------------------------------------------------------------------

const setDebugFiles = new Set<string>()

let indentLevel = 0
let lLogLines: string[] = []

export const INDENT = Symbol('indent')
export const UNDENT = Symbol('undent')

// ---------------------------------------------------------------------------

export const openDebugFile = (
		stub: string,
		clear: boolean = false
		): void => {

	const path = `./logs/${stub}.log`
	setDebugFiles.add(path)
	if (clear && existsSync(path)) {
		Deno.removeSync(path)
	}
	return
}

// ---------------------------------------------------------------------------

export const appendDebugFile = (
		...lItems: unknown[]
		): void => {

	for (const item of lItems) {
		const block = (typeof item === 'string') ? item : toJSON(item)
		for (const path of setDebugFiles) {
			Deno.writeTextFileSync(path, block + "\n", {append: true})
		}
	}
	return
}

// ---------------------------------------------------------------------------

export const closeDebugFile = (stub: string): void => {

	const path = `src/logs/${stub}.log`
	setDebugFiles.delete(path)
	return
}

// ---------------------------------------------------------------------------

export const curLogLevel = (): TLogLevel => {

	return logLevel
}

// ---------------------------------------------------------------------------

export const initLogLevel = (
		level: TLogLevel
		): void => {

	lLogLevels = [level]
	logLevel = level
	console.log(`INITIAL LOG LEVEL set to ${level}`)
	return
}

// ---------------------------------------------------------------------------

export const pushLogLevel = (
		level: TLogLevel
		): void => {

	lLogLevels.push(level)
	logLevel = level
	return
}

// ---------------------------------------------------------------------------

export const popLogLevel = (): void => {

	if (lLogLevels.length === 0) {
		throw new Error("Empty lLogLevels in pop()")
	}
	logLevel = lLogLevels.pop() || 'info'
	if (logLevel === undefined) {
		throw new Error("Empty lLogLevels in pop()")
	}
	return
}

// ---------------------------------------------------------------------------

export const toJSON = (item: unknown): string => {

	return JSON.stringify(item, null, 3)
}

// ---------------------------------------------------------------------------

export const LOG = (
		...lItems: unknown[]
		): void => {

	if (logLevel === 'silent') {
		return
	}
	for (const item of lItems) {
		if (item === INDENT) {
			indentLevel += 1
		}
		else if (item === UNDENT) {
			if (indentLevel > 0) {
				indentLevel -= 1
			}
		}
		else {
			logLine(item)
		}
	}
	return
}

// ---------------------------------------------------------------------------

export const DBG = (
		...lItems: unknown[]
		): void => {

	// --- if an append file is defined, output even if
	//     current log level is not 'debug'
	appendDebugFile(...lItems)

	if (curLogLevel() === 'debug') {
		LOG(...lItems)
	}
	return
}

// ---------------------------------------------------------------------------

export const WARN = (
		msg: string,
		label: string = 'WARN'
		): void => {

	lLogLines.push(msg)
	if (logLevel === 'silent') {
		return
	}
	console.error(yellow(label) + ': ' + msg)
	return
}

// ---------------------------------------------------------------------------

export const ERR = (
		msg: string,
		label: string = 'ERR'
		): void => {

	lLogLines.push(msg)
	if (logLevel === 'silent') {
		return
	}
	console.error(red(label) + ': ' + msg)
	return
}

// ---------------------------------------------------------------------------
// --- Make sure lines have no trailing whitespace

export const getLog = (): string => {

	const lLines: string[] = []     // --- should contain no NL chars
	for (const block of lLogLines) {
		for (const line of block.split('\n')) {
			lLines.push(line.replace(/\s+$/, ''))
		}
	}
	return lLines.join('\n')
}

// ---------------------------------------------------------------------------

const logLine = (
		x: unknown,
		): void => {

	const line = '\t'.repeat(indentLevel) + unknownToString(x)
	if (logLevel !== 'testing') {
		console.log(line.replaceAll('\t', '   '))
	}
	lLogLines.push(line)
	return
}

// ---------------------------------------------------------------------------

export const clearLog = (): void => {

	lLogLines.length = 0
	return
}

// ---------------------------------------------------------------------------

export const unknownToString = (x: unknown): string => {

	return (
		  (typeof x === 'string') ? x
		: (x === undefined)       ? 'undef'
		: (x === null)            ? 'null'
		:                          JSON.stringify(x)
		)
}

